#include <iostream>
#include <algorithm>
#include <iomanip>
#include <string>
using namespace std;

using ll = long long;

const ll maxd = 18;
const ll maxd2 = 1LL << maxd;
const ll maxm = 100;

string n;
ll m;
ll dp[maxd2][maxm];
ll fact[maxd + 1];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;

    ll s = static_cast<ll>(n.size());
    ll s2 = 1LL << s;

    dp[0][0] = 1;

    for (ll mask = 0; mask < s2; ++mask) {
        for (ll j = 0; j < s; ++j) {
            if ((mask >> j) & 1LL) {
                ll previous = mask ^ (1LL << j);

                if (previous == 0 && n[j] == '0')
                    continue;

                for (ll remainder = 0; remainder < m; ++remainder) {
                    ll nextRemainder =
                        (remainder * 10 + n[j] - '0') % m;
                    dp[mask][nextRemainder] += dp[previous][remainder];
                }
            }
        }
    }

    fact[0] = 1;
    for (ll i = 1; i <= maxd; ++i)
        fact[i] = fact[i - 1] * i;

    ll answer = dp[s2 - 1][0];

    for (char digit = '0'; digit <= '9'; ++digit)
        answer /= fact[count(n.begin(), n.end(), digit)];

    cout << answer << '\n';
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <array>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string n;
    int m;
    cin >> n >> m;

    array<int, 10> count{};
    for (char c : n) {
        ++count[c - '0'];
    }

    array<int, 10> multiplier{};
    int states = 1;
    for (int digit = 0; digit < 10; ++digit) {
        multiplier[digit] = states;
        states *= count[digit] + 1;
    }

    vector<long long> dp(static_cast<size_t>(states) * m);
    dp[0] = 1;

    for (int state = 0; state < states; ++state) {
        for (int digit = 0; digit < 10; ++digit) {
            int used = (state / multiplier[digit]) % (count[digit] + 1);
            if (used == count[digit] || (state == 0 && digit == 0)) {
                continue;
            }

            int nextState = state + multiplier[digit];
            for (int remainder = 0; remainder < m; ++remainder) {
                dp[static_cast<size_t>(nextState) * m +
                   (remainder * 10 + digit) % m] +=
                    dp[static_cast<size_t>(state) * m + remainder];
            }
        }
    }

    cout << dp[static_cast<size_t>(states - 1) * m] << '\n';
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <array>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string n;
    int m;
    cin >> n >> m;

    array<int, 10> count{};
    for (char c : n) {
        ++count[c - '0'];
    }

    array<int, 10> stride{};
    int states = 1;
    for (int digit = 0; digit < 10; ++digit) {
        stride[digit] = states;
        states *= count[digit] + 1;
    }

    vector<ll> dp(static_cast<size_t>(states) * m, 0);
    dp[0] = 1;

    for (int state = 0; state < states; ++state) {
        for (int digit = 0; digit < 10; ++digit) {
            int used = (state / stride[digit]) % (count[digit] + 1);
            if (used == count[digit]) {
                continue;
            }
            if (state == 0 && digit == 0) {
                continue;
            }

            int nextState = state + stride[digit];
            for (int remainder = 0; remainder < m; ++remainder) {
                ll ways = dp[static_cast<size_t>(state) * m + remainder];
                if (ways == 0) {
                    continue;
                }

                int nextRemainder = (remainder * 10 + digit) % m;
                dp[static_cast<size_t>(nextState) * m + nextRemainder] += ways;
            }
        }
    }

    cout << dp[static_cast<size_t>(states - 1) * m] << '\n';
    return 0;
}

#include <algorithm>
#include <cstdint>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string n;
    int m;
    cin >> n >> m;

    sort(n.begin(), n.end());

    const int s = static_cast<int>(n.size());
    const int totalMasks = 1 << s;

    vector<vector<int>> levels(s + 1);
    vector<int> index(totalMasks, -1);

    for (int mask = 0; mask < totalMasks; ++mask) {
        bool canonical = true;
        for (int j = 1; j < s; ++j) {
            if ((mask & (1 << j)) && n[j] == n[j - 1] &&
                !(mask & (1 << (j - 1)))) {
                canonical = false;
                break;
            }
        }

        if (canonical) {
            levels[__builtin_popcount(static_cast<unsigned>(mask))].push_back(mask);
        }
    }

    for (int level = 0; level <= s; ++level) {
        for (int i = 0; i < static_cast<int>(levels[level].size()); ++i) {
            index[levels[level][i]] = i;
        }
    }

    vector<vector<int>> nextRemainder(10, vector<int>(m));
    for (int digit = 0; digit < 10; ++digit) {
        for (int remainder = 0; remainder < m; ++remainder) {
            nextRemainder[digit][remainder] = (remainder * 10 + digit) % m;
        }
    }

    auto advance = [&](const auto& current, auto& next, int level) {
        for (int row = 0; row < static_cast<int>(levels[level].size()); ++row) {
            const int mask = levels[level][row];
            const size_t currentBase = static_cast<size_t>(row) * m;

            for (int j = 0; j < s; ++j) {
                if (mask & (1 << j)) continue;
                if (level == 0 && n[j] == '0') continue;
                if (j > 0 && n[j] == n[j - 1] &&
                    !(mask & (1 << (j - 1)))) {
                    continue;
                }

                const int newMask = mask | (1 << j);
                const size_t nextBase =
                    static_cast<size_t>(index[newMask]) * m;
                const int digit = n[j] - '0';

                for (int remainder = 0; remainder < m; ++remainder) {
                    const auto value = current[currentBase + remainder];
                    if (value != 0) {
                        next[nextBase + nextRemainder[digit][remainder]] += value;
                    }
                }
            }
        }
    };

    vector<uint32_t> current32(static_cast<size_t>(m), 0);
    current32[0] = 1;

    const int smallLevels = min(s, 12);
    for (int level = 0; level < smallLevels; ++level) {
        vector<uint32_t> next(
            static_cast<size_t>(levels[level + 1].size()) * m, 0);
        advance(current32, next, level);
        current32.swap(next);
    }

    const int fullMask = totalMasks - 1;
    const size_t answerPosition =
        static_cast<size_t>(index[fullMask]) * m;

    if (s <= 12) {
        cout << current32[answerPosition] << '\n';
        return 0;
    }

    vector<uint64_t> current64(
        static_cast<size_t>(levels[13].size()) * m, 0);
    advance(current32, current64, 12);

    for (int level = 13; level < s; ++level) {
        vector<uint64_t> next(
            static_cast<size_t>(levels[level + 1].size()) * m, 0);
        advance(current64, next, level);
        current64.swap(next);
    }

    cout << current64[answerPosition] << '\n';
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <iomanip>
using namespace std;

using ll = long long;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    string n;
    int m;
    cin >> n >> m;

    const int s = static_cast<int>(n.size());
    const int maskCount = 1 << s;

    vector<vector<ll>> dp(maskCount, vector<ll>(m, 0));
    dp[0][0] = 1;

    for (int mask = 1; mask < maskCount; ++mask) {
        for (int j = 0; j < s; ++j) {
            if (!(mask & (1 << j))) continue;

            const int previousMask = mask ^ (1 << j);
            if (previousMask == 0 && n[j] == '0') continue;

            for (int remainder = 0; remainder < m; ++remainder) {
                const int nextRemainder =
                    (remainder * 10 + (n[j] - '0')) % m;
                dp[mask][nextRemainder] += dp[previousMask][remainder];
            }
        }
    }

    vector<ll> factorial(s + 1, 1);
    for (int i = 1; i <= s; ++i) {
        factorial[i] = factorial[i - 1] * i;
    }

    ll answer = dp[maskCount - 1][0];
    for (char digit = '0'; digit <= '9'; ++digit) {
        answer /= factorial[count(n.begin(), n.end(), digit)];
    }

    cout << answer << '\n';
    return 0;
}

